Sure! Here's a JavaScript function that swaps the positions of adjacent words in a string until the adjectives come before the noun:

```js
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  let currentPosition = 0;
  let isNounFound = false;

  // Loop through the array of words and swap adjacent words until we find the noun
  while (!isNounFound && currentPosition < words.length - 1) {
    const firstWord = words[currentPosition];
    const secondWord = words[currentPosition + 1];

    // If both words are adjectives (start with 'a', 'an', or 'the'), swap them
    if (firstWord.match(/^[at]/) && secondWord.match(/^[at]/)) {
      words[currentPosition] = secondWord;
      words[currentPosition + 1] = firstWord;
    } else if (secondWord === "are" || secondWord === "is") {
      // We've found the noun, exit the loop
      isNounFound = true;
    }

    currentPosition++;
  }

  // Join the swapped words back into a sentence
  return words.join(" ");
}
```

