#include <iostream>
#include <string>
#include <limits> // for numeric_limits
#include <cmath> // for pow()

// Recursive Fibonacci function
unsigned long long fib(int n, int& prev1, int& prev2) {
    if (n <= 1) {
        return n;
    }

    unsigned long long result = fib(n - 1, prev2, prev1);
    int temp = prev1;
    prev1 = prev2;
    prev2 = result;
    return temp + result;
}

int main() {
    int first, second, numElements;

    std::cout << "Enter the first Fibonacci number: ";
    while (!(std::cin >> first)) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << "Invalid input! Please enter an integer: ";
    }

    std::cout << "Enter the second Fibonacci number: ";
    while (!(std::cin >> second)) {
        std::cin.clear();
        std::cin.ignore(std::numeric_limits<std::streamsize>::max(), '\n');
        std::cout << "Invalid input! Please enter an integer: ";
