    int prev1 = first, prev2 = second;

    std::cout << "Fibonacci sequence (" << first << ", " << second << "): ";
    for (int I = 0; I < numElements; i++) {
        std::cout << fib(i, prev1, prev2) << " ";
    }
    std::cout << "\n";

    return 0;
}
