// Recursive function to generate Fibonacci sequence
std::vector<int> fibonacci(int n, int a, int b) {
    if (n <= 0) {
        // Base case: empty sequence
        std::vector<int> result;
        return result;
    }
    std::vector<int> result = fibonacci(n - 1, a, b);
    result.push_back(a);
    a = b;
    b = result.back();
    result.pop_back();
    result.insert(result.end(), a, b);
    return result;
}

