To solve this problem, we'll define an array of tuples containing all homophone pairs we want to replace. Then, we'll iterate through each word in the input passage and check if it matches any of the homophones. If so, we'll replace it with the corresponding replacement word from the tuple.

Here's the Swift implementation:

```swift
let homophones = [
    ("there", "they're"),
    ("their", "there"),
    ("they're", "there"),
    ("too", "to"),
    ("two", "too"),
]

func replaceHomophones(input: String) -> String {
    var output = ""
    let words = input.components(separatedBy: .whitespacesAndNewlines)

    for (i, word) in words.enumerated() {
        let lowercasedWord = word.lowercased()

        for (homoFrom, homoTo) in homophones {
            let startIndex = lowercasedWord.index(of: homoFrom)

            // Check if the whole word matches the homophone
            guard let _ = Range(startIndex, in: lowercasedWord) else { continue }

            // Replace the homophone with the replacement word
            output += String(lowercasedWord[..<startIndex]) + homoTo + String(lowercasedWord[(lowercasedWord.distance(from: startIndex, to: lowercasedWord.endIndex))...])

            // Update the index of the next word to account for the inserted characters
            i += homoTo.count - homoFrom.count
            break
        }

        // Add the unchanged word to the output string
        output += String(word)
    }

    return output
}

