function showDesktopWallpaper() {
	// use the html5 canvas element to capture the desktop screen
	var canvas = document.createElement('canvas');
	var context = canvas.getContext('2d');
	canvas.width = screen.width;
	canvas.height = screen.height;
	context.drawwindow(null);
	// encode the captured desktop wallpaper as base64 data
	var dataurl = canvas.todataurl();
	// update the body background image with the new base64 encoded wallpaper
	document.getelementsbytagname('body')[0].style.backgroundimage = "url('" + dataurl + "')";
}
```

