To efficiently extract and organize data from multiple sources with varying formats into a coherent timeline, you can follow these steps using R:

1. Define a function that accepts a data source (XML, CSV, or JSON) as input and returns a list containing the necessary information for each development in chronological order. This function will be called for each data source separately.

```R
extract_data <- function(source) {
  if (str_detect(source, ".xml")) {
    # Extract data from XML source
    library(XML)
    doc <- xmlTreeParse(source)
    events <- vector("list", length=xmlSize(doc))

    for (i in seq(xmlSize(doc))) {
      node <- xmlNode(doc)[[i]]

      title <- xmlValue(node[@title])
      date <- as.Date(xmlValue(node[@date]), format="%Y-%m-%d")
      description <- xmlValue(node[@description], trim=TRUE)

      events[[i]] <- c(title, date, description)
    }

    return(events)
  } else if (str_detect(source, ".csv")) {
    # Extract data from CSV source
    library(readr)
    df <- read_csv(source)

    events <- vector("list", nrow(df))
    for (i in seq_len(nrow(df))) {
      events[[i]] <- c(df$Title[i], as.Date(df$Date, format="%Y-%m-%d"), df$Description[i])
    }

    return(events)
  } else if (str_detect(source, ".json")) {
    # Extract data from JSON source
    library(jsonlite)
    data <- fromJSON(source)

    events <- vector("list", length=length(data$Events))
    for (i in seq_len(length(data$Events))) {
      events[[i]] <- c(data$Events[[i]]$Title, as.Date(data$Events[[i]]$Date), data$Events[[i]]$Description)
    }

