    const { name, position, randomize } = input[i];

    let index = position - 1;

    if (randomize) {
      // Generate a random index within the bounds of the output array
      index = Math.floor(Math.random() * output.length);
    }

    output.splice(index, 0, { name });
  }

  return output;
}

