      {template ? (
        <>
          <h1>{template.sentence}</h1>
          <Form template={template} submissions={submissions} />
          <ResponseList submissions={submissions} />
        </>
      ) : (
        <p>Loading...</p>
      )}
    </div>
  );
}

export default App;
```

