    mutationRate = 0.01;
    offspring = parentIndices(1) + (parentIndices(2) - parentIndices(1)) * randn(1, populationSize) / sqrt(mutationRate);
    offspring(offspring < 1) = 1;
    offspring(offspring > populationSize) = populationSize;
    % Update population with new generation
    population = [population population(~isnan(offspring))] / 2;
    generation++;
    % Check if convergence is reached
    if max(abs(diff(histcounts(population(:), 'bin', 0:populationSize)))) <= 1e-6
        disp('Convergence reached after ' int(generation) ' generations');
        break;
    end
end

% Visualize evolution process
figure;
plot(histcounts(population(:), 'bin', 0:populationSize));
xlabel('Individual');
ylabel('Frequency');
title(['Evolution after ' num2str(generation) ' generations']);
```

