import { ExecutionContext, Injectable } from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class DevelopmentMiddleware {
  constructor(private readonly developmentEnvironment: boolean) {}

  public static use(): any[] {
    return [DevelopmentMiddleware];
  }

  public execute(context: ExecutionContext): Observable<any> {
    const req = context.switchToHttp().getRequest();

    if (req.env === 'development') {
      return super.execute(context).pipe(map(() => true));
    }

    return new Observable(() => {});
  }
}
```

