import { AppService } from './app.service';

@Module({
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule {
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(DevelopmentMiddleware).forRoutes('*');
  }
}
```

In this example, we're applying the middleware to all routes by passing `'*'` to `forRoutes`. You can replace that with specific routes or controllers as needed.

