// Listen for messages from content scripts
chrome.runtime.onMessage.addListener(function (message) {
  // Check if message is from a content script
  if (message.from === "content_script") {
    // Inject script into current tab
    chrome.tabs.executeScript(message.tabId, { file: "inject.js" });
  }
});

// Register context menu item
chrome.contextMenus.create({
  "id": "my-extension-menu-item",
  "title": "Inject Script",
  "contexts": ["all"],
  "documenturlpatterns": ["https://example.com/*"]
});

// Handle context menu item click event
chrome.contextMenus.onClicked.addListener(function (info, tab) {
  // Send message to background script to inject script
  chrome.tabs.sendMessage(tab.id, { from: "content_script" });
});
