import { Downshift } from "react-downshift";
import { useSearchEmails } from "./search-emails";

export const EmailInput = () => {
  const { results, isLoading, handleKeyDown } = useSearchEmails();

  return (
    <Downshift id="email-input" itemToString={(item) => item.email} {...{ results, isLoading }} handleKeyDown={handleKeyDown}>
      {({ getRootProps, getInputProps, getMenuProps, highlightedIndex }) => (
        <div {...getRootProps()}>
          <input type="text" {...getInputProps()} />
          {isLoading && <span>Loading...</span>}
          {results.length > 0 && (
            <ul {...getMenuProps()} className="menu">
              {results.map((result, index) => (
                <li key={result.id} className={index === highlightedIndex ? "highlighted" : ""} role="option">
                  {result.name} <span className="email">({result.email})</span>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </Downshift>
  );
};
```

In this component, we're importing the `useSearchEmails` hook from another file (which we'll create next). The `Downshift` component takes care of managing the autocomplete functionality, and we pass it some props to configure its behavior.

