```swift
func rearrangePhrase(_ phrase: String) -> String {
    let positiveLetters = ["u", "r", "t", "h", "a", "c", "k"]
    let sortedLetters = (phrase.filter { !$0.isWhitespace } + positiveLetters).shuffled().prefix(30)
