Here's the implementation of `RedisClient` class in the `redis.js` file:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('connect', () => {
      console.log('Connected to Redis');
    });
    this.client.on('error', err => {
      console.error('Error connecting to Redis:', err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error('Error checking Redis connection:', err);
      return false;
    }
  }

  async get(key) {
    return this.client.get(key);
  }

  async set(key, value, ttl) {
    await this.client.setex(key, ttl, value);
  }

  async del(key) {
    return this.client.del(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

The `constructor` sets up the Redis client with event listeners for connect and error events. The `isAlive` method checks if the Redis connection is alive by attempting to ping the server. The other methods are asynchronous functions for getting, setting, and deleting values in Redis. Note that we're using the `setex` command to set a key with a TTL (Time To Live). This command sets both the key and the expiration time in seconds at once.

Here's an implementation of the `RedisClient` class based on your requirements:

```javascript
const { promisify } = require('util');
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => console.error('Redis Client Error', err));
  }

  isAlive() {
    return this.client.ping().then(() => true).catch(() => false);
  }

  async get(key) {
    const value = await promisify(this.client.get)(key);
    return value;
  }

  async set(key, value, duration) {
    await promisify(this.client.setex)(key, duration, value);
  }

  async del(key) {
    await promisify(this.client.del)(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

I used `promisify` from the `util` module to convert the synchronous Redis methods into their asynchronous counterparts. This allows us to use them directly in our async functions without having to worry about callbacks or Promises chaining.

The `isAlive` method checks whether the connection to Redis is alive by attempting to ping the server. If the server responds successfully, we resolve with `true`, otherwise we reject with `false`.

The `get`, `set`, and `del` methods are all asynchronous and wrap the respective Redis commands with `promisify`. They return their corresponding values once resolved.

