I do not have access to your active directory environment to test this script, but here's a powershell script that implements the described functionality:

```powershell
# define variables for output and logging
$output = @()
$log = "acl_check.log"

# define functions for checking sid existence and logging results
function checksid($sid) {
    $users = get-aduser -filter { sidhistory -like "*$sid*" } | select-object -expandproperty sidhistory
    $groups = get-adgroup -filter { members -like "*$sid*" } | select-object -expandproperty members
    return ($users.count + $groups.count) > 0
}

function logresult($message) {
    add-content $log "$(get-date -format "yyyy-MM-dd HH:mm:ss") - $message"
}

# function to recursively check acl on folder and subfolders
function checkfolderacl($path) {
    try {
        $acls = get-acla $path
        foreach ($acl in $acls) {
            foreach ($access in $acl.access) {
                $sid = [security.principal.ntsecurityidentifier]$access.identityreference
                $isvalid = checksid($sid.value)
                if (!$isvalid) {
                    $entry = new-psobject -property @{
                        Path = $path
                        Sid = $sid.value
                        IsValid = $false
                    }
                    $output += $entry
                    logresult("invalid sid '$sid.value' found in acl of '$path'" )
                }
            }
            foreach ($inheritancerule in $acl.inheritancerules) {
                checkfolderacl $inheritancerule.path
            }
        }
    } catch {
        # handle errors like permission denied
        logresult("error: $_")
    }
}

# main script execution
try {
    checkfolderacl "c:\path\to\folder"
    logresult("finished running script.")
} catch {
    logresult("error: $_")
}

